class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def isPalindrome(self, head: ListNode) -> bool:
    vals = []
    p = head
    while p:
        vals.append(p.val)
        p = p.next
    left, right = 0, len(vals) - 1
    while left < right:
        if vals[left] != vals[right]:
            return False
        left += 1
        right -= 1
    return True

code.java:
public boolean isPalindrome(ListNode head) {
    if (head == null || head.next == null) {
        return true;
    }
    // 1. find middle (slow ends at start of 2nd half / the middle)
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
    }
    // 2. reverse from slow to the end
    ListNode prev = null, curr = slow;
    while (curr != null) {
        ListNode nxt = curr.next;
        curr.next = prev;
        prev = curr;
        curr = nxt;
    }
    // 3. compare first half with reversed second half
    ListNode left = head, right = prev;
    boolean ok = true;
    while (right != null) {
        if (left.val != right.val) {
            ok = false;
            break;
        }
        left = left.next;
        right = right.next;
    }
    // 4. (optional) restore the second half
    ListNode prev2 = null, cur2 = prev;
    while (cur2 != null) {
        ListNode nxt = cur2.next;
        cur2.next = prev2;
        prev2 = cur2;
        cur2 = nxt;
    }
    return ok;
}

